import com.android.sdklib.AndroidVersion;
import com.android.sdklib.AndroidTargetHash;
import com.android.sdklib.repository.meta.DetailsTypes;
class SdkIdentifierProbe {
  public static void main(String[] args) {
    for (String input : new String[]{"android-36", "android-37", "android-37.0"}) {
      AndroidVersion version = AndroidTargetHash.getVersionFromHash(input);
      if (version == null) throw new AssertionError(input);
      String path = DetailsTypes.getPlatformPath(version);
      System.out.println(input + " -> api=" + version.getApiString() + ", package=" + path);
      if (input.startsWith("android-37") && !path.equals("platforms;android-37.0")) throw new AssertionError(path);
    }
  }
}
